/// <summary>
/// Transfer order shipment confirmation class
/// </summary>
class METOrderShipmentConfirmation_TransferOrder extends METOrderShipmentConfirmation
{
}

Method.Source:
/// <summary>
/// If the transfer order is a CSD or a Cross dock order, then it should be auto received
/// </summary>
/// <param name = "_transferId">Transfer order number to check if this can be auto-received</param>
/// <returns>Yes if the order should be auto received, otherwise false</returns>
private NoYes shouldAutoReceive(InventTransferId _transferId)
{
    METInventTransferTableExt transExt;
    InventTransferTable trans;
    NoYes ret = NoYes::No;

    select firstonly TransferType from transExt
        exists join trans
        where trans.RecId == transExt.InventTransferTable
        && trans.TransferId == _transferId;

    if (transExt.TransferType == METCrossDockTransferType::CSD)
    {
        ret = NoYes::Yes;
    }
    else if (transExt.TransferType == METCrossDockTransferType::CrossDock)
    {
        ret = NoYes::Yes;

        InventTransferLine inventTransferLine;
        METInventTransferLine metInventTransferLine;

        select firstonly RecId from metInventTransferLine
            exists join inventTransferLine
            where metInventTransferLine.InventTransferLine == inventTransferLine.RecId
            && inventTransferLine.TransferId == _transferId
            && metInventTransferLine.SalesId == '';

        if (metInventTransferLine)
        {
            ret = checkFailed("@GLS111731");
        }
    }

    return ret;
}

/// <summary>
/// Business logic to post/ship the transfer order
/// </summary>
/// <returns>Boolean flag</returns>
public boolean post()
{
    METSalesOrderShipmentLoadLines  shipmentLoadLines;
    InventTransferParmTable         inventTransferParmTable;
    InventTransferUpd               invTranUpd;
    InventTransferJour              inventTransferJour;
    InventTransferTable             inventTransferTable;
    boolean                         ret;
    InventParameters inventParameters = InventParameters::find();

    documentStatus = DocumentStatus::None;

    while select shipmentLoadLines
        group by OrderNum
        where shipmentLoadLines.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId
        exists join inventTransferTable
            where shipmentLoadLines.OrderNum == inventTransferTable.TransferId  &&
                inventTransferTable.TransferStatus == InventTransferStatus::Created
    {
        inventTransferParmTable.clear();
        inventTransferParmTable.initParmDefault();
        inventTransferParmTable.ParmId = RunBaseMultiParm::getSysParmId();
        inventTransferParmTable.TransferId = shipmentLoadLines.OrderNum;
        inventTransferParmTable.UpdateType = InventTransferUpdateType::Shipment;
        inventTransferParmTable.PrintTransferReceipt = NoYes::No;
        inventTransferParmTable.AutoReceiveQty = this.shouldAutoReceive(shipmentLoadLines.OrderNum);
        inventTransferParmTable.ShipUpdateQty = InventTransferShipUpdateQty::PickedQty; //The code is changed from All to PickedQty for a bug_201064
        inventTransferParmTable.EditLines = NoYes::Yes;
        inventTransferParmTable.ExplodeLines = NoYes::No;
        inventTransferParmTable.TransDate = metSalesOrderShipmentLoadHeader.ConfirmedShipDate;
        inventTransferParmTable.InventDimFixedReceiveList = 0;
        inventTransferParmTable.insert();

        invTranUpd = InventTransferUpdShip::newParmBuffer(inventTransferParmTable);

        invTranUpd.run();

        inventTransferJour = invTranUpd.parmInventTransferJour();

        if (inventTransferJour.RecId)
        {
            inventTransferJour.selectForUpdate(true);
            inventTransferJour.METShipmentId = metSalesOrderShipmentLoadHeader.ShipmentId;
            inventTransferJour.METLoadId     = metSalesOrderShipmentLoadHeader.LoadId;
            InventTransferjour.update();


            //CB238 - xDock process sales orders linked to transfer orders.
            //CB238 - if supply from transfer is enabled for the LE, we need to perform additional validations and sales picking and posting.
            METCrossDockSalesFinalizationFacade::construct().process(shipmentLoadLines.OrderNum);

            ret = true;
        }
    }

    return ret;
}

/// <summary>
/// Check if wave details need to be created in the system for the sales order
/// </summary>
/// <param name = "_salesTable">Table buffer of of <t>SalesTable</t></param>
/// <param name = "_inventLocation">Table buffer of type <t>InventLocation</t></param>
/// <returns>true if wave is required, otherwise false</returns>
private boolean isWaveRequired(SalesTable _salesTable, InventLocation _inventLocation)
{
    boolean ret = false;

    if (_salesTable.salesid && DateTimeUtil::minValue() != _salesTable.METOrderExtractDateTime
            && _inventLocation.METWaveRequired == NoYes::Yes && _inventLocation.METCSDWarehouse == NoYes::Yes
            && _inventLocation.METPickDirector == NoYes::Yes)
    {
        ret = true;
    }

    return ret;
}

/// <summary>
/// Run method to initiate business logic.
/// </summary>
public void run()
{
    super();

    //CB629_TMSEngineTOShipped.
    //Calling it out of the transaction scope set in the <c>METOrderShipmentConfirmation</c> run method.
    //It will avoid rollback of entire order confirmation in case there is an error in TMS.
    METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::TransferOrderShipped, metSalesOrderShipmentLoadHeader).run();
}
